def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    candidates = set()

    # Zero cells tucked against several sides of the 5-pattern form the
    # small interior pockets; connected larger pockets are colored 8.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            n5 = sum(
                0 <= r + dr < h and 0 <= c + dc < w and
                grid[r + dr][c + dc] == 5
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1))
            )
            if n5 >= 2:
                candidates.add((r, c))

    seen = set()
    for cell in candidates:
        if cell in seen:
            continue
        comp = [cell]
        seen.add(cell)
        for r, c in comp:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nxt = (r + dr, c + dc)
                if nxt in candidates and nxt not in seen:
                    seen.add(nxt)
                    comp.append(nxt)
        color = 7 if len(comp) <= 4 else 8
        for r, c in comp:
            out[r][c] = color
    return out
